class Solution {
public:
    bool containsPattern(vector<int>& arr, int m, int k) {
        int n = arr.size();
        int target = m * (k - 1);
        int count = 0;
        for (int j = 0; j + m < n; j++) {
            if (arr[j] == arr[j + m]) {
                count++;
                if (count >= target) return true;
            } else {
                count = 0;
            }
        }
        return false;
    }
};
